#include <array>
#include <iostream>

bool is_even(int value) {
    return value % 2 == 0;
}

int main() {
    for (int value : std::array{1, 2, 3, 4}) {
        if (is_even(value)) std::cout << value << '\n';
    }
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

int main() {
    const std::vector<std::string> words{"go", "stay", "go"};
    std::unordered_map<std::string, int> counts;
    for (const auto& word : words) {
        ++counts[word];
    }
    std::cout << counts.at("go") << '\n';
}

#include <iostream>

class Counter {
public:
    void increment() { ++value; }
    int get() const { return value; }
private:
    int value{0};
};

void show(const Counter& counter) {
    std::cout << counter.get() << '\n';
}

int main() {
    Counter counter;
    counter.increment();
    show(counter);
}

#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> scores{3, 9, 5, 7};
    std::sort(scores.begin(), scores.end());
    int threshold = 6;
    auto high = std::count_if(scores.begin(), scores.end(),
                              [threshold](int score) { return score >= threshold; });
    std::cout << scores.front() << ", " << high << '\n';
}

